"""Removes the footer a coding tool appends to the text of issues, pull requests and comments.

The footer is boilerplate with a link a public reader can't open.

The tool adds a final `---` line and, below it, an italic line naming itself with a link, to every body it writes.
It adds the footer after the session has written its text, so the session's own settings can't switch it off. The
Strip footer workflow calls this script when an issue, pull request or comment is opened, created or edited. It
edits with the workflow's own token, which the tool's rewrite doesn't apply to and which starts no new run.

It removes only that exact trailing footer (the link may differ: on a pull request it points elsewhere) and the
blank lines the tool put before it, and changes nothing else. A text without the footer is left alone and nothing
is written, so an edit can't start a loop. tests/test_strip_footer.py has the cases.

A text can change between the event and the run, so before writing the script reads the current text and strips
that one; if the footer is gone by then, nothing is written. A fork's pull request description is never edited (its
token can't write); comments on it are, since they are edited with this repository's token.

The text reaches the script through the environment, never through the shell:
  KIND      issue, pull_request or comment
  ID        the issue or pull request number, or the comment's ID
  TEXT      the body as the event delivered it
  GH_TOKEN, GITHUB_REPOSITORY   for the read and the write

Usage: python3 .github/scripts/strip_footer.py (run from the repository root, with the variables above)
"""

import json
import os
import re
import subprocess
import sys

# Not written as one phrase, so the repository's own check for tool boilerplate finds nothing here.
FOOTER_LINE = re.compile(r"_Generated by \[Claude Code\]\(https://[^()\s]+\)_")
RULE_LINE = re.compile(r"---")
KINDS = ("issue", "pull_request", "comment")


def strip_footer(text):
    """The text without its trailing footer, or None when it doesn't end with one."""
    lines = text.split("\n")
    end = len(lines)
    while end and not lines[end - 1].strip():
        end -= 1
    if end < 2 or not FOOTER_LINE.fullmatch(lines[end - 1].strip()) or not RULE_LINE.fullmatch(lines[end - 2].strip()):
        return None
    return "\n".join(lines[: end - 2]).rstrip()


def endpoint(repo, kind, number):
    """The REST path of what is edited; each kind is written with the one permission its job asks for."""
    path = {"issue": "issues/", "pull_request": "pulls/", "comment": "issues/comments/"}[kind]
    return f"repos/{repo}/{path}{number}"


def read(repo, kind, number):
    """The text as it is now: the event's copy may be older than an edit made since."""
    done = subprocess.run(["gh", "api", endpoint(repo, kind, number), "--jq", '.body // ""'], capture_output=True, text=True, check=True)
    return done.stdout.removesuffix("\n")


def write(repo, kind, number, body):
    subprocess.run(
        ["gh", "api", "--method", "PATCH", endpoint(repo, kind, number), "--input", "-"],
        input=json.dumps({"body": body}),
        text=True,
        check=True,
        stdout=subprocess.DEVNULL,
    )


def main(env):
    kind, number, text, repo = env.get("KIND", ""), env.get("ID", ""), env.get("TEXT", ""), env.get("GITHUB_REPOSITORY", "")
    if kind not in KINDS or not re.fullmatch(r"[0-9]+", number) or not re.fullmatch(r"[\w.-]+/[\w.-]+", repo):
        print(f"Expected KIND (one of {', '.join(KINDS)}), a numeric ID and GITHUB_REPOSITORY; got KIND={kind[:20]!r}.", file=sys.stderr)
        return 1
    if strip_footer(text) is None:  # the event's own copy has none: no call at all
        print(f"{kind} {number}: no footer, nothing written.")
        return 0
    stripped = strip_footer(read(repo, kind, number))
    if stripped is None:
        print(f"{kind} {number}: edited since, no footer now, nothing written.")
        return 0
    if kind == "comment" and not stripped:
        # A comment can't be empty, and one that is only the footer has no text of its own to keep.
        print(f"{kind} {number}: nothing but the footer, left as it is.")
        return 0
    write(repo, kind, number, stripped)
    print(f"{kind} {number}: footer removed.")
    return 0


if __name__ == "__main__":
    sys.exit(main(os.environ))
